export function getSkillMeta(slug: string): SkillMeta | null {
  return SKILL_META[slug] ?? null
}

export function getSkillsByScore(maxScore: number): string[] {
  return Object.entries(SKILL_META)
    .filter(([, m]) => m.score <= maxScore)
    .sort(([, a], [, b]) => a.score - b.score)
    .map(([slug]) => slug)
}
